style.css:
@-moz-document domain("amazon.pl") {
/* =========================
   Amazon.pl - GitHub Dark Gray
   ========================= */

:root {
    --gh-bg: #0d1117;
    --gh-bg-alt: #161b22;
    --gh-bg-soft: #21262d;
    --gh-border: #30363d;
    --gh-text: #c9d1d9;
    --gh-muted: #8b949e;
    --gh-link: #58a6ff;
    --gh-link-hover: #79c0ff;
    --gh-accent: #238636;
    --gh-warning: #d29922;
}

/* Tło globalne */
html, body, #a-page, #dp, #gp, #pageContent {
    background: var(--gh-bg) !important;
    color: var(--gh-text) !important;
}

/* Tekst */
body, div, span, p, li, td, th, label, h1, h2, h3, h4, h5, h6 {
    color: var(--gh-text) !important;
}

/* Muted / secondary text */
.a-color-secondary,
.a-size-base-color-secondary,
.a-color-tertiary,
.s-color-subdued,
#glow-ingress-line2,
#nav-link-accountList-nav-line-1,
#nav-orders .nav-line-1,
#nav-cart .nav-line-1,
.navFooterDescText,
.a-text-normal {
    color: var(--gh-muted) !important;
}

/* Linki */
a,
a span,
.a-link-normal,
.a-link-normal span,
.a-text-bold a {
    color: var(--gh-link) !important;
}

a:hover,
a:hover span,
.a-link-normal:hover,
.a-link-normal:hover span {
    color: var(--gh-link-hover) !important;
}

/* Header / navbar */
#navbar,
#nav-belt,
#nav-main,
#nav-subnav,
#nav-xshop,
#nav-tools,
#nav-logo,
#nav-progressive-subnav,
.nav-searchbar,
#nav-search {
    background: var(--gh-bg-alt) !important;
    color: var(--gh-text) !important;
    border-color: var(--gh-border) !important;
}

/* Elementy w headerze */
#nav-xshop .nav-a,
#nav-tools .nav-a,
#nav-logo-text,
#nav-hamburger-menu,
#nav-cart,
#nav-orders,
#nav-link-accountList {
    color: var(--gh-text) !important;
}

/* Pole wyszukiwania */
#nav-search-bar-form,
.nav-search-field,
#twotabsearchtextbox,
.nav-input,
input[type="text"],
input[type="search"],
input[type="email"],
input[type="password"],
input:not([type]),
textarea,
select {
    background: var(--gh-bg) !important;
    color: var(--gh-text) !important;
    border: 1px solid var(--gh-border) !important;
    box-shadow: none !important;
}

input::placeholder,
textarea::placeholder {
    color: var(--gh-muted) !important;
}

/* Przyciski */
button,
input[type="submit"],
input[type="button"],
.a-button,
.a-button-inner,
.a-button-text,
.a-button-input {
    background: var(--gh-bg-soft) !important;
    color: var(--gh-text) !important;
    border: 1px solid var(--gh-border) !important;
    box-shadow: none !important;
}

/* Primary-ish button */
#add-to-cart-button,
#buy-now-button,
#a-autoid-announce,
.a-button-primary .a-button-inner {
    background: #1f6feb !important;
    color: #ffffff !important;
    border-color: #388bfd !important;
}

/* Hover */
button:hover,
input[type="submit"]:hover,
input[type="button"]:hover,
.a-button:hover,
.a-button-primary:hover .a-button-inner,
.a-button-inner:hover {
    filter: brightness(1.08) !important;
}

/* Karty, boksy, sekcje */
.a-box,
.a-box-inner,
.a-cardui,
.a-section,
.a-container,
.a-popover-inner,
.a-dropdown-container,
.a-expander-container,
.s-card-container,
.s-result-item,
[data-component-type="s-search-result"],
[data-asin],
.sg-col-inner,
.celwidget,
#desktop_buybox,
#buybox,
#apex_desktop,
#centerCol,
#leftCol,
#rightCol,
#productDescription,
#feature-bullets,
#detailBullets_feature_div,
#reviewsMedley,
#cm-cr-dp-review-list,
#navFooter,
#twister,
#ppd {
    background: var(--gh-bg-alt) !important;
    color: var(--gh-text) !important;
    border-color: var(--gh-border) !important;
    box-shadow: none !important;
}

/* Delikatne oddzielenie sekcji */
.a-box,
.a-cardui,
.s-card-container,
[data-component-type="s-search-result"],
#buybox,
#desktop_buybox {
    border: 1px solid var(--gh-border) !important;
    border-radius: 6px !important;
}

/* Search results */
.s-main-slot .s-result-item,
.s-widget-container,
.sg-col-4-of-24,
.sg-col-20-of-24 {
    background: transparent !important;
}

/* Sidebar / filtry */
#s-refinements,
#s-refinements * {
    background-color: transparent !important;
}

#s-refinements .a-section,
#s-refinements .a-spacing-none,
#s-refinements .a-expander-content {
    background: var(--gh-bg-alt) !important;
    color: var(--gh-text) !important;
}

/* Tabele */
table,
tr,
td,
th,
tbody,
thead {
    background: var(--gh-bg-alt) !important;
    color: var(--gh-text) !important;
    border-color: var(--gh-border) !important;
}

/* Dropdowny / popupy */
.a-popover-wrapper,
.a-popover,
.a-dropdown,
.a-menu,
.a-menu-item,
.a-fixed-left-grid-inner,
.a-fixed-right-grid-inner {
    background: var(--gh-bg-alt) !important;
    color: var(--gh-text) !important;
    border-color: var(--gh-border) !important;
}

/* Footer */
#navFooter,
#navFooter * ,
.navFooterBackToTop,
.navFooterVerticalColumn,
.navFooterLinkCol,
.navFooterDescLine,
.navLeftFooter {
    background: var(--gh-bg-alt) !important;
    color: var(--gh-muted) !important;
    border-color: var(--gh-border) !important;
}

/* Cena */
.a-price .a-offscreen,
.a-price-whole,
.a-price-fraction,
.a-color-price,
.a-text-price {
    color: var(--gh-warning) !important;
}

/* Tytuł produktu */
#productTitle {
    color: #e6edf3 !important;
}

/* Gwiazdki / rating */
.a-icon-alt,
.a-star-medium,
.a-star-mini,
.a-star-small {
    color: #f2cc60 !important;
}

/* Breadcrumbs, meta info */
#wayfinding-breadcrumbs_feature_div,
#wayfinding-breadcrumbs_feature_div * {
    color: var(--gh-muted) !important;
}

/* Checkboxy / radio / small controls */
input[type="checkbox"],
input[type="radio"] {
    accent-color: #2f81f7 !important;
}

/* Jasne tła w inline styles */
[style*="background:#fff"],
[style*="background: #fff"],
[style*="background-color:#fff"],
[style*="background-color: #fff"],
[style*="background:white"],
[style*="background: white"],
[style*="background-color:white"],
[style*="background-color: white"] {
    background: var(--gh-bg-alt) !important;
}

/* Jasny tekst na jasnym tle - korekta */
[style*="color:#000"],
[style*="color: #000"],
[style*="color:black"],
[style*="color: black"] {
    color: var(--gh-text) !important;
}

/* Hover na kafelkach */
.s-result-item:hover,
.s-card-container:hover,
.a-box:hover {
    background: var(--gh-bg-soft) !important;
}

/* Obrazki bez zmian */
img,
video {
    background: transparent !important;
}

/* Focus */
input:focus,
select:focus,
textarea:focus,
button:focus,
a:focus {
    outline: 1px solid #2f81f7 !important;
    outline-offset: 1px !important;
}

/* Zaznaczenie tekstu */
::selection {
    background: rgba(56, 139, 253, 0.35) !important;
    color: #ffffff !important;
}

/* Usuń jasne cienie */
* {
    box-shadow: none !important;
}

/* Delikatne separatory */
hr,
.a-divider.a-divider-section,
.a-section.a-spacing-none.a-divider-normal {
    border-color: var(--gh-border) !important;
    background: var(--gh-border) !important;
}
}
